        const node = ctx.createScriptProcessor(4096, 1, 1);
        const chunks = [];
        const onframe = [];
        node.onaudioprocess = (e) => {
          const f = new Float32Array(e.inputBuffer.getChannelData(0));
          chunks.push(f);
          onframe.forEach((cb) => cb(f, ctx.sampleRate));
        };
        src.connect(node);
        node.connect(ctx.destination);
